insert into test_account_pool (
    id, project_id, application_id, environment_id, code, name, status, lease_policy_json,
    default_ttl_seconds, created_by, updated_by, archived_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{applicationId}, #{environmentId}, #{code}, #{name}, #{status},
    cast(coalesce(#{leasePolicyJson}, '{}') as jsonb),
    #{defaultTtlSeconds}, #{createdBy}, #{updatedBy}, #{archivedAt}, #{createdAt}, #{updatedAt}
)

insert into test_account_lease (
    id, pool_id, account_id, project_id, status, holder_type, holder_ref,
    request_key, request_digest, lease_token_digest, expires_at, released_at, release_reason,
    created_by, created_at, updated_at
) values (
    #{id}, #{poolId}, #{accountId}, #{projectId}, #{status}, #{holderType}, #{holderRef},
    #{requestKey}, #{requestDigest}, #{leaseTokenDigest}, #{expiresAt}, #{releasedAt}, #{releaseReason},
    #{createdBy}, #{createdAt}, #{updatedAt}
)
on conflict do nothing

mapper.update:
update test_account_lease set
    expires_at = #{expiresAt},
    updated_at = #{updatedAt}
where id = #{id}
  and status = 'ACTIVE'

update test_account_lease set
    status = 'EXPIRED',
    release_reason = #{releaseReason},
    updated_at = #{updatedAt}
where id = #{id}
  and status = 'ACTIVE'

mapper.insert:
insert into test_data_task (
    id, project_id, data_set_id, task_type, status, request_key, target_ref,
    attempt, result_summary_json, error_code, error_summary, trace_id,
    created_by, started_at, finished_at, created_at, updated_at
) values (
    #{id}, #{projectId}, #{dataSetId}, #{taskType}, #{status}, #{requestKey}, #{targetRef},
    #{attempt}, cast(coalesce(#{resultSummaryJson}, '{}') as jsonb), #{errorCode}, #{errorSummary},
    #{traceId}, #{createdBy}, #{startedAt}, #{finishedAt}, #{createdAt}, #{updatedAt}
)
on conflict do nothing

mapper.update:
update test_data_task set
    status = #{status},
    request_key = #{requestKey},
    target_ref = #{targetRef},
    attempt = #{attempt},
    result_summary_json = cast(coalesce(#{resultSummaryJson}, '{}') as jsonb),
    error_code = #{errorCode},
    error_summary = #{errorSummary},
    trace_id = #{traceId},
    started_at = #{startedAt},
    finished_at = #{finishedAt},
    updated_at = #{updatedAt}
where id = #{id}
  and not exists (
      select 1
      from test_data_task
      where project_id = #{projectId}
        and request_key = #{requestKey}
        and id != #{id}
  )

update test_data_task set
    status = #{task.status},
    request_key = #{task.requestKey},
    target_ref = #{task.targetRef},
    attempt = #{task.attempt},
    result_summary_json = cast(coalesce(#{task.resultSummaryJson}, '{}') as jsonb),
    error_code = #{task.errorCode},
    error_summary = #{task.errorSummary},
    trace_id = #{task.traceId},
    started_at = #{task.startedAt},
    finished_at = #{task.finishedAt},
    updated_at = #{task.updatedAt}
where id = #{task.id}
  and status in ('FAILED','CANCELED')
  and attempt = #{expectedAttempt}
  and not exists (
      select 1
      from test_data_task
      where project_id = #{task.projectId}
        and request_key = #{task.requestKey}
        and id != #{task.id}
  )

